/// A grid of rows x cols cells starts as all water. The cells (r, c) in
/// cells are turned into land one at a time, in order. Two land cells belong
/// to the same island when they are connected through land cells that share
/// an edge (up, down, left, right; diagonals do not connect).
///
/// After each step, record (number of islands, size of the largest island in
/// cells), with (0, 0) when there is no land. Return the vector of records, one
/// per element of cells.
///
/// A cell outside the grid (r outside 0 .. rows-1 or c outside 0 .. cols-1;
/// when rows <= 0 or cols <= 0 every cell is outside) or a cell that is
/// already land changes nothing, but still produces a record.
/// >>> island_counts(3, 3, vec![(0, 0), (0, 1), (1, 2), (2, 1)])
/// vec![(1, 1), (1, 2), (2, 2), (3, 2)]
/// >>> island_counts(2, 2, vec![(0, 0), (1, 1), (0, 1)])
/// vec![(1, 1), (2, 1), (1, 3)]
fn island_counts(rows: i64, cols: i64, cells: Vec<(i64, i64)>) -> Vec<(i64, i64)> {
    fn find(parent: &mut Vec<usize>, mut x: usize) -> usize {
        while parent[x] != x {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        x
    }
    let inside = |r: i64, c: i64| r >= 0 && r < rows && c >= 0 && c < cols;
    let total = if rows > 0 && cols > 0 { (rows * cols) as usize } else { 0 };
    let mut parent: Vec<usize> = (0..total).collect();
    let mut size = vec![1i64; total];
    let mut land = vec![false; total];
    let (mut islands, mut largest) = (0i64, 0i64);
    let mut out = Vec::new();
    for &(r, c) in &cells {
        if inside(r, c) && !land[(r * cols + c) as usize] {
            let me = (r * cols + c) as usize;
            land[me] = true;
            islands += 1;
            for (nr, nc) in [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)] {
                if inside(nr, nc) && land[(nr * cols + nc) as usize] {
                    let a = find(&mut parent, me);
                    let b = find(&mut parent, (nr * cols + nc) as usize);
                    if a != b {
                        let (big, small) = if size[a] < size[b] { (b, a) } else { (a, b) };
                        parent[small] = big;
                        size[big] += size[small];
                        islands -= 1;
                    }
                }
            }
            let root = find(&mut parent, me);
            largest = largest.max(size[root]);
        }
        out.push((islands, largest));
    }
    out
}
